// SOIH - Caso: participación democrática en España (dentro de la UE)
// Fuente única del modelo. Todo lo demás (CSV, resumen.json, mapa, simulador) se genera con soih_engine.js.
// Primera versión: 25/10/2026, traducción del núcleo del caso (investigacion/foco/nucleo_*.csv) y del módulo de
// riqueza (investigacion/foco/modulo_riqueza*.csv). Cómo se tradujo: datos/NOTAS_CONSTRUCCION.md y la cabecera
// de datos/traducir_nucleo.js. Estado: borrador de trabajo, sin publicar.
//
// Pregunta central: ¿qué hace que más gente participe en las decisiones democráticas, y qué votos y políticas
// consiguen que más personas vivan con dignidad, con sus derechos respetados y con menos rabia?
//
// REGLAS DE REGISTRO (las del método, que el motor hace cumplir):
//  1. Una afirmación se enlaza a una relación solo si afirma ese vínculo. Aquí no hay afirmaciones de actores:
//     el inventario recoge estudios, así que todas las relaciones tienen percepción P0 y su confianza sale del
//     nivel de datos.
//  2. El nivel de datos (D1 o superior) exige una fuente escrita en «evidencia».
//  3. La evidencia de otro país cuenta como D1 y se rotula «Referencia de otro país».
//  4. Una relación sin fuente es hipótesis del analista: H(). Las de lectura pendiente (solo resumen, nota de
//     prensa o cita) también van como H(), con la marca «pendiente».
//  5. Las identidades contables van con C().
// Ningún signo lleva juicio de valor: P59 (ideología del gobierno) usa la convención técnica «+ = más a la
// izquierda». Lo que es mejor para la ciudadanía se juzga en las variables de resultado, con la misma vara.
'use strict';

// ---------------------------------------------------------------- Dominios (clusters)
const clusters = [
  { id: 'E', nombre: 'Económico', descripcion: 'Renta, desigualdad, empleo, impuestos y gasto público.' },
  { id: 'S', nombre: 'Sociológico y demográfico', descripcion: 'Estatus, actitudes, vínculos sociales y composición de la población.' },
  { id: 'P', nombre: 'Político-electoral', descripcion: 'Participación, voto, polarización, reglas electorales y respuesta de las políticas.' },
  { id: 'T', nombre: 'Tecnológico y mediático', descripcion: 'Noticias, redes, desinformación y cambio tecnológico.' },
  { id: 'L', nombre: 'Legal-institucional', descripcion: 'Calidad democrática, justicia, corrupción, confianza y derechos.' },
  { id: 'M', nombre: 'Módulo de riqueza (bloque aparte)', descripcion: 'Riqueza acumulada y renta generada, como módulo separado del núcleo (decisión de 23/10/2026) hasta el modelo con cantidades. Casi todo son identidades contables e hipótesis; el eslabón riqueza → poder político → reglas fiscales no existe ni como hipótesis.' }
];

// ---------------------------------------------------------------- Constructores
const variables = [];
// v(id, nombre, definicion, tipo, indicador, fuente, cluster, extra). La escala no la declara el inventario: «pendiente».
function v(id, nombre, definicion, tipo, indicador, fuente, cluster, extra) {
  variables.push(Object.assign({ id, nombre, definicion, tipo, unidad: '', escala: 'pendiente', indicador, fuente, cluster, frontera: tipo === 'exogena' ? 'exogena' : 'endogena' }, extra || {}));
}
const edges = [];
// e(id, de, a, pol, mecanismo, retardo, D, evidencia, contra, extra). El id es el de la relación en el inventario.
function e(id, de, a, pol, mecanismo, retardo, D, evidencia, contra, extra) {
  edges.push(Object.assign({ id, de, a, pol, mecanismo, retardo, D, statements: [], evidencia: evidencia || '', contra: contra || '' }, extra || {}));
}
// H(...) = hipótesis del analista o lectura pendiente: sin fuente que cuente; fuera del cálculo principal
function H(id, de, a, pol, mecanismo, retardo, contra, extra) { e(id, de, a, pol, mecanismo, retardo, 'D0', '', contra || '', Object.assign({ hipotesis: true }, extra || {})); }
// C(...) = identidad contable: cierta por definición, no es evidencia de conducta
function C(id, de, a, pol, mecanismo, retardo, evidencia, extra) { e(id, de, a, pol, mecanismo, retardo, 'D3', evidencia || 'Identidad contable.', '', Object.assign({ contable: true }, extra || {})); }

